%%%-------------------------------------------------------------------
%%% @doc
%%% command_examples.erl - 遥控指令示例帧数据模块
%%%
%%% 本模块提供所有遥控指令（1~46）的 EB90 帧示例数据，
%%% 用于测试验证，避免主模块代码臃肿。
%%%
%%% 协议对应：procotol.docx 中的遥控指令表（开关指令、载荷控制等）
%%% 每个示例帧是按照 EB90 链路层格式构造的完整二进制数据，
%%% 包含同步头、地址、数据类型、载荷、CRC 等。
%%% 示例帧可直接用于模拟地面站发送遥控指令。
%%%
%%% @end
%%%-------------------------------------------------------------------
-module(dgiot_uav_command_examples).

-export([get_command_example/1]).

%% @doc 根据指令编号返回对应的 EB90 帧二进制数据
%% 参数 Code 为 1..46 的整数，对应协议中定义的指令序号
%% 如果指令编号无对应示例，返回空二进制 <<>>
%% 示例帧结构：
%%   - 字节 0-1: 同步头 EB 90
%%   - 字节 2-3: 目的地址 (0x0012)
%%   - 字节 4-5: 源地址 (0x0000)
%%   - 字节 6:   平台/数据类型 (0x61，即平台类型6，数据类型1)
%%   - 字节 7:   帧计数 (0x00)
%%   - 字节 8-10: 密钥 (0x000000)
%%   - 字节 11-12: CRC (填充0)
%%   - 字节 13-14: 载荷子帧头 A5 5A
%%   - 字节 15-...: 载荷内容（包含飞机型号、ID、命令ID、数据）
%%   - 最后2字节: CRC（实际有效）
%% @end
-spec get_command_example(integer()) -> binary().
get_command_example(Code) ->
    case Code of
        1 -> <<16#EB,16#90,16#00,16#12,16#00,16#00,16#61,16#00,16#00,16#00,16#00,16#A5,16#5A,16#00,16#00,16#00,16#F0,16#A7,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#54,16#77,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00,16#00>>;
